#include <algorithm>
#include <iostream>
#include <vector>
using namespace std;
static bool ok(const vector<long long>& h,long long cut,long long need){ long long total=0; for(long long x:h){ if(x>cut) total+=x-cut; if(total>=need) return true; } return total>=need; }
int main(){ int n; long long need; if(!(cin>>n>>need)) return 0; vector<long long> h(n); long long hi=0; for(int i=0;i<n;i++){ cin>>h[i]; hi=max(hi,h[i]); } long long lo=0, ans=0; while(lo<=hi){ long long mid=lo+(hi-lo)/2; if(ok(h,mid,need)){ ans=mid; lo=mid+1; } else hi=mid-1; } cout<<ans<<'\n'; return 0; }
